//! Depression filling.
//!
//! Terrain generated by tectonics contains closed basins: craters, rift floors
//! and glacial hollows. Water cannot flow out of a basin until it fills to the
//! lowest spill point. Terra uses the Priority-Flood algorithm (Barnes, Lehman
//! and Mulla, 2014): ocean cells are pushed into a min-heap, and the lowest
//! frontier cell always expands next, raising any enclosed neighbor to a level
//! just above the current frontier.
//!
//! A small epsilon is added per step so the filled surface has no flat plateaus
//! and a deterministic downhill direction exists everywhere. The original
//! elevation is preserved; the difference between the two is water depth for
//! closed lakes.

use std::cmp::Ordering;
use std::collections::BinaryHeap;

use crate::sphere::Sphere;

/// Result of a priority flood.
#[derive(Clone, Debug)]
pub struct Filled {
    /// Water surface elevation after filling, in meters. Always at least the
    /// original elevation.
    pub level: Vec<f64>,
    /// Cells in the order they were finalized, from low to high. Reversing this
    /// order gives a valid downstream-first processing order for flow
    /// accumulation.
    pub order: Vec<u32>,
}

/// Elevation added per step. Small enough that a lake surface is flat to within
/// centimeters, large enough to avoid exact ties in floating point.
pub const DEFAULT_EPSILON: f64 = 1e-3;

#[derive(Clone, Copy, Debug)]
struct HeapCell {
    level: f64,
    cell: u32,
}

impl PartialEq for HeapCell {
    fn eq(&self, other: &Self) -> bool {
        self.level.total_cmp(&other.level) == Ordering::Equal && self.cell == other.cell
    }
}

impl Eq for HeapCell {}

impl PartialOrd for HeapCell {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for HeapCell {
    fn cmp(&self, other: &Self) -> Ordering {
        // Reverse so BinaryHeap (a max-heap) pops the lowest level first. The
        // cell index breaks ties deterministically.
        other
            .level
            .total_cmp(&self.level)
            .then_with(|| other.cell.cmp(&self.cell))
    }
}

impl Filled {
    /// Number of cells.
    pub fn len(&self) -> usize {
        self.level.len()
    }

    /// True when no cells were processed.
    pub fn is_empty(&self) -> bool {
        self.level.is_empty()
    }

    /// Maximum water depth above the original surface.
    pub fn max_depth(&self, original: &[f64]) -> f64 {
        self.level
            .iter()
            .zip(original)
            .map(|(l, o)| (l - o).max(0.0))
            .fold(0.0, f64::max)
    }
}

/// Fills closed depressions and records the processing order.
pub fn priority_flood(sphere: &Sphere, elevation: &[f64], epsilon: f64) -> Filled {
    let n = sphere.len().min(elevation.len());
    let epsilon = if epsilon.is_finite() && epsilon > 0.0 {
        epsilon.clamp(1e-6, 1.0)
    } else {
        DEFAULT_EPSILON
    };
    let mut level = vec![f64::NEG_INFINITY; n];
    let mut visited = vec![false; n];
    let mut order = Vec::with_capacity(n);
    let mut heap = BinaryHeap::new();

    let mut seed = |cell: u32, visited: &mut Vec<bool>, heap: &mut BinaryHeap<HeapCell>| {
        let i = cell as usize;
        if i < n && !visited[i] {
            visited[i] = true;
            level[i] = elevation[i];
            heap.push(HeapCell {
                level: elevation[i],
                cell,
            });
        }
    };

    let mut has_ocean = false;
    for i in 0..n {
        if elevation[i] <= 0.0 {
            has_ocean = true;
            seed(i as u32, &mut visited, &mut heap);
        }
    }
    if !has_ocean && n > 0 {
        // No water: seed the global minimum so the algorithm still terminates.
        let mut best = 0u32;
        for i in 1..n {
            if elevation[i] < elevation[best as usize] {
                best = i as u32;
            }
        }
        seed(best, &mut visited, &mut heap);
    }

    while let Some(top) = heap.pop() {
        order.push(top.cell);
        for &nb in sphere.neighbors(top.cell) {
            let ni = nb as usize;
            if ni >= n || visited[ni] {
                continue;
            }
            visited[ni] = true;
            let raised = top.level + epsilon;
            let lvl = if elevation[ni] > raised {
                elevation[ni]
            } else {
                raised
            };
            level[ni] = lvl;
            heap.push(HeapCell {
                level: lvl,
                cell: nb,
            });
        }
    }

    // Disconnected meshes are impossible for a sphere, but keep every value
    // finite if the input slice was shorter than expected.
    for i in 0..n {
        if !visited[i] {
            level[i] = elevation[i];
            order.push(i as u32);
        }
    }
    Filled { level, order }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn flat_sphere(level: f64) -> (Sphere, Vec<f64>) {
        let s = Sphere::new(2);
        let e = vec![level; s.len()];
        (s, e)
    }

    #[test]
    fn ocean_surface_is_untouched() {
        let s = Sphere::new(3);
        let mut e = vec![500.0; s.len()];
        for i in 0..s.len() {
            if s.lat(i as u32) < -30.0 {
                e[i] = -100.0;
            }
        }
        let f = priority_flood(&s, &e, DEFAULT_EPSILON);
        for i in 0..s.len() {
            assert!(f.level[i] >= e[i] - 1e-12);
            if e[i] <= 0.0 {
                assert_eq!(f.level[i], e[i]);
            }
        }
        assert_eq!(f.len(), s.len());
        assert_eq!(f.order.len(), s.len());
    }

    #[test]
    fn closed_pit_fills_to_the_spill() {
        let s = Sphere::new(2);
        let mut e = vec![100.0; s.len()];
        // A ring of high ground around a single low cell.
        let pit = 50u32;
        for &nb in s.neighbors(pit) {
            e[nb as usize] = 300.0;
        }
        e[pit as usize] = 10.0;
        // Guarantee an ocean so the pit is not the seed.
        e[0] = -50.0;
        let f = priority_flood(&s, &e, DEFAULT_EPSILON);
        assert!(f.level[pit as usize] > e[pit as usize]);
        assert!(f.level[pit as usize] >= 300.0);
        for &nb in s.neighbors(pit) {
            assert!(f.level[nb as usize] >= 300.0);
        }
    }

    #[test]
    fn filled_is_never_below_original() {
        let s = Sphere::new(3);
        let mut e: Vec<f64> = (0..s.len())
            .map(|i| ((i as f64 * 12.9898).sin() * 400.0).round())
            .collect();
        e[5] = -3000.0;
        let f = priority_flood(&s, &e, DEFAULT_EPSILON);
        for (l, o) in f.level.iter().zip(&e) {
            assert!(*l >= *o - 1e-9);
            assert!(l.is_finite());
        }
    }

    #[test]
    fn flat_terrain_is_fully_filled() {
        let (s, e) = flat_sphere(250.0);
        let f = priority_flood(&s, &e, DEFAULT_EPSILON);
        // A flat planet with no ocean gets one seed and an epsilon ramp, so the
        // maximum deviation is bounded by n * epsilon.
        assert!(f.max_depth(&e) <= s.len() as f64 * DEFAULT_EPSILON + 1e-9);
        assert!(f.level.iter().all(|l| *l >= 250.0));
    }

    #[test]
    fn order_is_a_permutation() {
        let s = Sphere::new(3);
        let e: Vec<f64> = (0..s.len()).map(|i| ((i * 7) % 97) as f64).collect();
        let f = priority_flood(&s, &e, DEFAULT_EPSILON);
        let mut seen = vec![false; s.len()];
        for &c in &f.order {
            assert!(!seen[c as usize]);
            seen[c as usize] = true;
        }
        assert!(seen.iter().all(|&s| s));
    }

    #[test]
    fn order_is_nondecreasing() {
        let s = Sphere::new(3);
        let e: Vec<f64> = (0..s.len()).map(|i| ((i * 13) % 431) as f64).collect();
        let f = priority_flood(&s, &e, DEFAULT_EPSILON);
        for w in f.order.windows(2) {
            assert!(f.level[w[0] as usize] <= f.level[w[1] as usize] + 1e-9);
        }
    }

    #[test]
    fn deterministic() {
        let s = Sphere::new(3);
        let e: Vec<f64> = (0..s.len()).map(|i| ((i * 31) % 211) as f64).collect();
        let a = priority_flood(&s, &e, DEFAULT_EPSILON);
        let b = priority_flood(&s, &e, DEFAULT_EPSILON);
        assert_eq!(a.order, b.order);
        assert_eq!(a.level, b.level);
    }

    #[test]
    fn bad_epsilon_is_sanitized() {
        let s = Sphere::new(1);
        let e = vec![10.0; s.len()];
        for eps in [0.0, -1.0, f64::NAN, 1e9] {
            let f = priority_flood(&s, &e, eps);
            assert!(f.level.iter().all(|l| l.is_finite()));
        }
    }

    #[test]
    fn empty_input_is_safe() {
        let s = Sphere::new(0);
        let f = priority_flood(&s, &[], DEFAULT_EPSILON);
        assert_eq!(f.len(), 0);
        assert!(f.is_empty());
        // A full-length input still works at the coarse level.
        let e = vec![1.0; s.len()];
        let f = priority_flood(&s, &e, DEFAULT_EPSILON);
        assert_eq!(f.len(), s.len());
        assert!(f.level.iter().all(|l| l.is_finite()));
    }
}
